"""Primitive-relation independence generated by dimension contraction.

For a slot-transfer graph, contracting a primitive relation identifies its two
endpoint slots.  A set of relations is called contraction-independent when every
one of its edges can be contracted in sequence and each contraction lowers the
relation rank by exactly one.  This happens exactly when the selected edges form
a forest.

Hence maximal independent relation sets are spanning forests (spanning trees in
a connected geometry), all of the same size N-c.  The traditional graphic
matroid is therefore a combinatorial shadow of which primitive causal relations
represent independent dimension losses.  Matroid terminology/theory is mature
prior art; the project point is the causal interpretation and its bridge to
transfer geometry and boundary contraction.
"""

from __future__ import annotations

from dataclasses import dataclass
from itertools import combinations

from .causal_transfer_graph_geometry import Edge, transfer_components, transfer_relation_rank


def _normalize(slot_count: int, edges: tuple[Edge, ...]) -> tuple[Edge, ...]:
    normalized = set()
    for left, right in edges:
        if left == right or any(
            isinstance(index, bool)
            or not isinstance(index, int)
            or not (0 <= index < slot_count)
            for index in (left, right)
        ):
            raise ValueError("edges must contain distinct valid slots")
        normalized.add(tuple(sorted((left, right))))
    return tuple(sorted(normalized))


def relation_set_is_independent(slot_count: int, relations: tuple[Edge, ...]) -> bool:
    """Forest criterion: every selected relation contributes one rank drop."""
    edges = _normalize(slot_count, relations)
    return transfer_relation_rank(slot_count, edges) == len(edges)


def relation_set_rank(slot_count: int, relations: tuple[Edge, ...]) -> int:
    return transfer_relation_rank(slot_count, _normalize(slot_count, relations))


def relation_nullity(slot_count: int, relations: tuple[Edge, ...]) -> int:
    edges = _normalize(slot_count, relations)
    return len(edges) - relation_set_rank(slot_count, edges)


def maximal_independent_size(slot_count: int, allowed_edges: tuple[Edge, ...]) -> int:
    """Maximum independent relation count equals N - component count."""
    edges = _normalize(slot_count, allowed_edges)
    return transfer_relation_rank(slot_count, edges)


def is_spanning_relation_basis(slot_count: int, allowed_edges: tuple[Edge, ...], basis: tuple[Edge, ...]) -> bool:
    allowed = set(_normalize(slot_count, allowed_edges))
    selected = set(_normalize(slot_count, basis))
    if not selected <= allowed:
        return False
    return (
        relation_set_is_independent(slot_count, tuple(selected))
        and relation_set_rank(slot_count, tuple(selected))
        == relation_set_rank(slot_count, tuple(allowed))
    )


def spanning_relation_bases(slot_count: int, allowed_edges: tuple[Edge, ...]) -> tuple[tuple[Edge, ...], ...]:
    allowed = _normalize(slot_count, allowed_edges)
    rank = relation_set_rank(slot_count, allowed)
    return tuple(
        subset
        for subset in combinations(allowed, rank)
        if is_spanning_relation_basis(slot_count, allowed, subset)
    )


def basis_exchange_witness(
    slot_count: int,
    allowed_edges: tuple[Edge, ...],
    left_basis: tuple[Edge, ...],
    right_basis: tuple[Edge, ...],
    removed_edge: Edge,
) -> Edge | None:
    """Find an edge from right\left replacing removed edge while preserving a basis."""
    if not is_spanning_relation_basis(slot_count, allowed_edges, left_basis):
        raise ValueError("left_basis must be a spanning relation basis")
    if not is_spanning_relation_basis(slot_count, allowed_edges, right_basis):
        raise ValueError("right_basis must be a spanning relation basis")
    removed = tuple(sorted(removed_edge))
    left = set(_normalize(slot_count, left_basis))
    right = set(_normalize(slot_count, right_basis))
    if removed not in left - right:
        raise ValueError("removed_edge must belong to left_basis but not right_basis")
    reduced = left - {removed}
    for candidate in sorted(right - left):
        trial = tuple(sorted(reduced | {candidate}))
        if is_spanning_relation_basis(slot_count, allowed_edges, trial):
            return candidate
    return None


@dataclass(frozen=True)
class RelationIndependenceProfile:
    slot_count: int
    allowed_relation_count: int
    relation_rank: int
    cycle_nullity: int
    basis_count: int


def relation_independence_profile(slot_count: int, allowed_edges: tuple[Edge, ...]) -> RelationIndependenceProfile:
    edges = _normalize(slot_count, allowed_edges)
    rank = relation_set_rank(slot_count, edges)
    bases = spanning_relation_bases(slot_count, edges)
    return RelationIndependenceProfile(
        slot_count=slot_count,
        allowed_relation_count=len(edges),
        relation_rank=rank,
        cycle_nullity=len(edges) - rank,
        basis_count=len(bases),
    )
